    #[test]
    fn test_dont_optimize_attr_accessor_polymorphic() {
        set_call_threshold(3);
        eval("
            class C
              attr_reader :foo, :bar

              def foo_then_bar
                @foo = 1
                @bar = 2
              end

              def bar_then_foo
                @bar = 3
                @foo = 4
              end
            end

            O1 = C.new
            O1.foo_then_bar
            O2 = C.new
            O2.bar_then_foo
            def test(o) = o.foo
            test O1
            test O2
        ");
        assert_snapshot!(hir_string("test"), @"
        fn test@<compiled>:20:
        bb1():
          EntryPoint interpreter
          v1:BasicObject = LoadSelf
          v2:CPtr = LoadSP
          v3:BasicObject = LoadField v2, :o@0x1000
          Jump bb3(v1, v3)
        bb2():
          EntryPoint JIT(0)
          v6:BasicObject = LoadArg :self@0
          v7:BasicObject = LoadArg :o@1
          Jump bb3(v6, v7)
        bb3(v9:BasicObject, v10:BasicObject):
          CondBranchHasType v10, ObjectSubclass[class_exact:C], bb6(), bb5()
        bb6():
          v18:ObjectSubclass[class_exact:C] = RefineType v10, ObjectSubclass[class_exact:C]
          PatchPoint NoSingletonClass(C@0x1008)
          PatchPoint MethodRedefined(C@0x1008, foo@0x1010, cme:0x1018)
          v32:BasicObject = GetIvar v18, :@foo
          Jump bb4(v32)
        bb5():
          v21:BasicObject = Send v10, :foo # SendFallbackReason: Send: polymorphic fallback
          Jump bb4(v21)
        bb4(v15:BasicObject):
          PatchPoint NoEPEscape(test)
          CheckInterrupts
          Return v15
        ");
    }

