    #[test]
    fn test_trigger_guard_type_recompilation() {
        // The first call transitions C's shape by defining @a, so the setivar shape
        // guard misses once and already spends a version during the Fixnum phase.
        // Leave room for one more version so the Float phase can recompile.
        set_max_versions(3);
        set_inline_threshold(0);
        eval("
            class C
              def f(x)
                @a = 1
                y = x + 1
                @a = y
              end
            end

            # As of 06/04/2026, zjit/src/options.rs uses 5 as the default number of profiles
            # Let's pick a number that is reasonably larger to ensure compilation, even if
            # the default value changes a bit
            num_to_compile = 30

            c = C.new

            # Repeatedly call an integer until this fast path gets JITed
            num_to_compile.times { c.f(1) }

        ");

        let iseq = crate::cruby::with_rubyvm(|| get_method_iseq("C.new", "f"));
        unsafe { crate::cruby::rb_zjit_profile_disable(iseq) };
        let mut intermediate_hir = iseq_to_hir(iseq).unwrap();
        intermediate_hir.optimize();
        intermediate_hir.validate().unwrap();
        let Insn::FixnumAdd { left, right, .. } = intermediate_hir.find(hir_return_value(&intermediate_hir)) else { panic!("expected the initial Fixnum fast path") };
        assert_hir_const(&intermediate_hir, right, VALUE::fixnum_from_usize(1));
        assert!(matches!(intermediate_hir.find(left), Insn::GuardType { guard_type, recompile: Some(_), .. } if guard_type.is_subtype(types::Fixnum)));
        assert!(!dispatch_chain_insns(&intermediate_hir).any(|insn| matches!(insn, Insn::Send { .. } | Insn::FloatAdd { .. })));
        let initial_hir = hir_string_function(&intermediate_hir);

        eval("
            # Supposed to be the same as the earlier Ruby method in this test
            num_to_compile = 30
            c = C.new
            # Call this with a float in order to trigger a guard failure
            # Do this enough times to cause a recompilation
            num_to_compile.times { c.f(1.5) }
        ");
        unsafe { crate::cruby::rb_zjit_profile_disable(iseq) };
        let mut final_hir = iseq_to_hir(iseq).unwrap();
        final_hir.optimize();
        final_hir.validate().unwrap();
        assert_eq!(dispatch_chain_insns(&final_hir).filter(|insn| matches!(insn, Insn::FixnumAdd { .. })).count(), 1);
        assert_eq!(dispatch_chain_insns(&final_hir).filter(|insn| matches!(insn, Insn::FloatAdd { .. })).count(), 1);
        let branches: Vec<_> = dispatch_chain_insns(&final_hir).filter_map(|insn| match insn {
            Insn::CondBranchHasType(data) => Some(data),
            _ => None,
        }).collect();
        assert_eq!(branches.len(), 2);
        assert!(branches.iter().any(|branch| branch.expected.bit_equal(types::Fixnum)));
        assert!(branches.iter().any(|branch| branch.expected.bit_equal(types::Flonum)));
        let (recv, args, state) = assert_hir_single_fallback(&final_hir, "+", SendPolymorphicFallback, 1, None);
        assert_hir_const(&final_hir, args[0], VALUE::fixnum_from_usize(1));
        let frame = final_hir.frame_state(state);
        assert_eq!(frame.locals().next().copied(), Some(recv));
        assert_eq!(frame.stack().copied().collect::<Vec<_>>(), vec![recv, args[0]]);
        assert!(branches.iter().all(|branch| final_hir.find_id(branch.val) == recv));
        // Both specialized arms and the generic tail must feed the value stored
        // into @a and returned, rather than replaying the arithmetic on a miss.
        let result = hir_return_value(&final_hir);
        let ivar = unsafe { rb_get_symbol_id(eval(":@a")) };
        assert!(dispatch_chain_insns(&final_hir).any(|insn| matches!(insn,
            Insn::SetIvar { id, val, .. } if *id == ivar && final_hir.find_id(*val) == result
        )));
        assert!(dispatch_chain_insns(&final_hir).any(|insn| matches!(insn,
            Insn::StoreField { id: FieldName::Id(id), val, .. } if *id == ivar && final_hir.find_id(*val) == result
        )));
        assert_eq!(eval("c = C.new; c.f(1) == 2 && c.f(1.5) == 2.5 && c.instance_variable_get(:@a) == 2.5"), Qtrue);
        assert_snapshot!(format!("Before recompilation:\n{initial_hir}\nAfter recompilation:\n{}", hir_string_function(&final_hir)), @"
        Before recompilation:
        fn f@<compiled>:4:
        bb1():
          EntryPoint interpreter
          v1:HeapBasicObject = LoadSelf
          v2:CPtr = LoadSP
          v3:BasicObject = LoadField v2, :x@0x1000
          Jump bb3(v1, v3)
        bb2():
          EntryPoint JIT(0)
          v7:HeapBasicObject = LoadArg :self@0
          v8:BasicObject = LoadArg :x@1
          Jump bb3(v7, v8)
        bb3(v11:HeapBasicObject, v12:BasicObject):
          v74:NilClass = Const Value(nil)
          v17:Fixnum[1] = Const Value(1)
          v20:CShape = LoadField v11, :shape_id@0x1001
          v21:CShape[0x1002] = Const CShape(0x1002)
          v22:CBool = IsBitEqual v20, v21
          CondBranch v22, bb5(), bb6()
        bb5():
          StoreField v11, :@a@0x1003, v17
          Jump bb4()
        bb6():
          v27:CShape[0x1004] = Const CShape(0x1004)
          v28:CBool = IsBitEqual v20, v27
          CondBranch v28, bb7(), bb8()
        bb7():
          StoreField v11, :@a@0x1003, v17
          v34:CShape[0x1002] = Const CShape(0x1002)
          StoreField v11, :shape_id@0x1001, v34
          Jump bb4()
        bb8():
          SetIvar v11, :@a, v17
          Jump bb4()
        bb4():
          PatchPoint NoEPEscape(f)
          v43:Fixnum[1] = Const Value(1)
          PatchPoint MethodRedefined(Integer@0x1008, +@0x1010, cme:0x1018)
          v72:Fixnum = GuardType v12, Fixnum recompile
          v73:Fixnum = FixnumAdd v72, v43
          v53:CShape = LoadField v11, :shape_id@0x1001
          v54:CShape[0x1002] = Const CShape(0x1002)
          v55:CBool = IsBitEqual v53, v54
          CondBranch v55, bb10(), bb11()
        bb10():
          StoreField v11, :@a@0x1003, v73
          Jump bb9()
        bb11():
          SetIvar v11, :@a, v73
          Jump bb9()
        bb9():
          PatchPoint NoEPEscape(f)
          CheckInterrupts
          Return v73

        After recompilation:
        fn f@<compiled>:4:
        bb1():
          EntryPoint interpreter
          v1:HeapBasicObject = LoadSelf
          v2:CPtr = LoadSP
          v3:BasicObject = LoadField v2, :x@0x1000
          Jump bb3(v1, v3)
        bb2():
          EntryPoint JIT(0)
          v7:HeapBasicObject = LoadArg :self@0
          v8:BasicObject = LoadArg :x@1
          Jump bb3(v7, v8)
        bb3(v11:HeapBasicObject, v12:BasicObject):
          v88:NilClass = Const Value(nil)
          v17:Fixnum[1] = Const Value(1)
          v20:CShape = LoadField v11, :shape_id@0x1001
          v21:CShape[0x1002] = Const CShape(0x1002)
          v22:CBool = IsBitEqual v20, v21
          CondBranch v22, bb5(), bb6()
        bb5():
          StoreField v11, :@a@0x1003, v17
          Jump bb4()
        bb6():
          v27:CShape[0x1004] = Const CShape(0x1004)
          v28:CBool = IsBitEqual v20, v27
          CondBranch v28, bb7(), bb8()
        bb7():
          StoreField v11, :@a@0x1003, v17
          v34:CShape[0x1002] = Const CShape(0x1002)
          StoreField v11, :shape_id@0x1001, v34
          Jump bb4()
        bb8():
          SetIvar v11, :@a, v17
          Jump bb4()
        bb4():
          PatchPoint NoEPEscape(f)
          v43:Fixnum[1] = Const Value(1)
          CondBranchHasType v12, Fixnum, bb11(), bb12()
        bb11():
          v49:Fixnum = RefineType v12, Fixnum
          PatchPoint MethodRedefined(Integer@0x1008, +@0x1010, cme:0x1018)
          v84:Fixnum = FixnumAdd v49, v43
          Jump bb9(v84)
        bb12():
          CondBranchHasType v12, Flonum, bb13(), bb10()
        bb13():
          v54:Flonum = RefineType v12, Flonum
          PatchPoint MethodRedefined(Float@0x1040, +@0x1010, cme:0x1048)
          v87:Float = FloatAdd v54, v43
          Jump bb9(v87)
        bb10():
          v57:BasicObject = Send v12, :+, v43 # SendFallbackReason: Send: polymorphic fallback
          Jump bb9(v57)
        bb9(v46:BasicObject):
          v65:CShape = LoadField v11, :shape_id@0x1001
          v66:CShape[0x1002] = Const CShape(0x1002)
          v67:CBool = IsBitEqual v65, v66
          CondBranch v67, bb15(), bb16()
        bb15():
          StoreField v11, :@a@0x1003, v46
          WriteBarrier v11, v46
          Jump bb14()
        bb16():
          SetIvar v11, :@a, v46
          Jump bb14()
        bb14():
          PatchPoint NoEPEscape(f)
          CheckInterrupts
          Return v46
        ");
    }

    // Helper that compiles with inlining enabled. Temporarily sets the inline
    // threshold, compiles and optimizes, then restores the original value.
    #[track_caller]
    fn hir_string_with_inlining(method: &str) -> String {
        let old_threshold = get_option!(inline_threshold);
        unsafe { OPTIONS.as_mut().unwrap().inline_threshold = 30; }
        let result = hir_string(method);
        unsafe { OPTIONS.as_mut().unwrap().inline_threshold = old_threshold; }
        result
    }

    #[test]
    fn test_inline_method_with_send() {
        // The callee-internal `x + x` Send gets specialized to FixnumAdd because the callee's
        // profile entries are merged into the caller's ProfileOracle during inlining.
        eval("
            def double(x)
              x + x
            end
            def test(n)
              double(n)
            end
            test(1)
            test(1)
        ");
        assert_snapshot!(hir_string_with_inlining("test"), @"
        fn test@<compiled>:6:
        bb1():
          EntryPoint interpreter
          v1:BasicObject = LoadSelf
          v2:CPtr = LoadSP
          v3:BasicObject = LoadField v2, :n@0x1000
          Jump bb3(v1, v3)
        bb2():
          EntryPoint JIT(0)
          v6:BasicObject = LoadArg :self@0
          v7:BasicObject = LoadArg :n@1
          Jump bb3(v6, v7)
        bb3(v9:BasicObject, v10:BasicObject):
          PatchPoint MethodRedefined(Object@0x1008, double@0x1010, cme:0x1018)
          v25:ObjectSubclass[class_exact*:Object@VALUE(0x1008)] = GuardType v9, ObjectSubclass[class_exact*:Object@VALUE(0x1008)] recompile
          PushInlineFrame :double, v25 (0x1040), num_args=1
          PatchPoint MethodRedefined(Integer@0x1060, +@0x1068, cme:0x1070)
          v46:Fixnum = GuardType v10, Fixnum recompile
          v48:Fixnum = FixnumAdd v46, v46
          PopInlineFrame
          PatchPoint NoEPEscape(test)
          CheckInterrupts
          Return v48
        ");
    }

    #[test]
    fn test_inline_method_with_multiple_returns() {
        // TODO: remove_trivial_block_params affects the entire CFG and runs before canonicalize.
        // This means that some optimizations from canonicalize that affect block params have regressed,
        // such as test_inline_method_with_multiple_returns in opt_tests.
        // If we make canonicalize global, we should be able to pass Fixnum instead of BasicObject to bb4

        // `clamp_nonneg` has two Return instructions (one from the early `return 0 if ...`,
        // one from the implicit trailing `x`). Inlining rewrites each Return to a Jump into
        // the continuation block, whose single Param merges the return values.
        eval("
            def clamp_nonneg(x)
              return 0 if x < 0
              x
            end
            def test(n)
              clamp_nonneg(n)
            end
            test(1)
            test(1)
        ");
        assert_snapshot!(hir_string_with_inlining("test"), @"
        fn test@<compiled>:7:
        bb1():
          EntryPoint interpreter
          v1:BasicObject = LoadSelf
          v2:CPtr = LoadSP
          v3:BasicObject = LoadField v2, :n@0x1000
          Jump bb3(v1, v3)
        bb2():
          EntryPoint JIT(0)
          v6:BasicObject = LoadArg :self@0
          v7:BasicObject = LoadArg :n@1
          Jump bb3(v6, v7)
        bb3(v9:BasicObject, v10:BasicObject):
          PatchPoint MethodRedefined(Object@0x1008, clamp_nonneg@0x1010, cme:0x1018)
          v25:ObjectSubclass[class_exact*:Object@VALUE(0x1008)] = GuardType v9, ObjectSubclass[class_exact*:Object@VALUE(0x1008)] recompile
          PushInlineFrame :clamp_nonneg, v25 (0x1040), num_args=1
          v34:Fixnum[0] = Const Value(0)
          PatchPoint MethodRedefined(Integer@0x1060, <@0x1068, cme:0x1070)
          v62:Fixnum = GuardType v10, Fixnum recompile
          v63:BoolExact = FixnumLt v62, v34
          v39:CBool = Test v63
          CondBranch v39, bb7(), bb6()
        bb7():
          v44:Fixnum[0] = Const Value(0)
          Jump bb4(v44)
        bb6():
          Jump bb4(v62)
        bb4(v56:Fixnum):
          PopInlineFrame
          PatchPoint NoEPEscape(test)
          CheckInterrupts
          Return v56
        ");
    }

